(function(){
const $id=id=>document.getElementById(id),player=$id('quran-audio'),verses=$id('verses');
function compactSetup(){const setup=document.querySelector('.quran-setup');if(!setup)return;setup.querySelector('.quran-setup-head small')?.remove();$id('turkish-reciter')?.closest('label')?.remove();setup.querySelector('.quran-setup-options>small')?.remove();const mode=$id('ayah-play-mode');if(mode){const label=mode.closest('label');if(label){label.classList.add('compact-mode');label.childNodes[0].textContent='İlerleme '}[...mode.options].forEach(o=>o.textContent=o.value==='manual'?'Manuel':'Otomatik')}}
function compactPlayers(){verses?.querySelectorAll('.v17-player').forEach(bar=>{if(bar.dataset.v25)return;bar.dataset.v25='1';const speed=bar.querySelector('.v17-speed'),volume=bar.querySelector('.v17-volume');if(speed){const wrap=document.createElement('span'),button=document.createElement('button');wrap.className='mini-pop mini-speed';button.type='button';button.className='mini-tool';button.textContent='1×';button.title='Oynatma hızı';speed.before(wrap);wrap.append(button,speed);button.onclick=e=>{e.stopPropagation();wrap.classList.toggle('open')};speed.onchange=()=>{button.textContent=speed.options[speed.selectedIndex].textContent;player.playbackRate=Number(speed.value);wrap.classList.remove('open')}}if(volume){const input=volume.querySelector('input'),wrap=document.createElement('span'),button=document.createElement('button');wrap.className='mini-pop mini-volume';button.type='button';button.className='mini-tool';button.textContent='🔊';button.title='Ses düzeyi';volume.before(wrap);wrap.append(button,input);volume.remove();button.onclick=e=>{e.stopPropagation();wrap.classList.toggle('open')};input.oninput=()=>{player.volume=Number(input.value);button.textContent=player.volume===0?'🔇':player.volume<.55?'🔉':'🔊'}}})}
document.addEventListener('click',e=>{if(!e.target.closest('.mini-pop'))document.querySelectorAll('.mini-pop.open').forEach(x=>x.classList.remove('open'))});new MutationObserver(compactPlayers).observe(verses,{childList:true,subtree:true});compactSetup();compactPlayers();
const portraits={'ar.alafasy':'https://static.qurancdn.com/images/reciters/6/mishary-rashid-alafasy-profile.jpeg?v=1','ar.abdulbasitmurattal':'https://commons.wikimedia.org/wiki/Special:Redirect/file/Abdul_Basit_%27Abd_us-Samad_with_King_Faisal.jpg?width=240','ar.husary':'https://commons.wikimedia.org/wiki/Special:Redirect/file/%D8%A8%D8%B7%D8%A7%D9%82%D8%A9_%D8%B4%D8%AE%D8%B5%D9%8A%D8%A9_%D9%84%D9%85%D8%AD%D9%85%D9%88%D8%AF_%D8%AE%D9%84%D9%8A%D9%84_%D8%A7%D9%84%D8%AD%D8%B5%D8%B1%D9%8A_(cropped).png?width=240','ar.minshawi':'https://www.aljazeera.net/wp-content/uploads/2022/04/2_auto_x2.jpg?resize=400%2C400','ar.abdurrahmaansudais':'https://commons.wikimedia.org/wiki/Special:Redirect/file/Abdul-Rahman_Al-Sudais_(Cropped,_2011).jpg?width=240','yasser-surah':'https://commons.wikimedia.org/wiki/Special:Redirect/file/Yasser_Al-dosari.jpg?width=240'};
function refreshPortrait(){const select=$id('arabic-reciter'),img=document.querySelector('.reciter-photo');if(!select||!img)return;img.src=portraits[select.value]||portraits['ar.alafasy'];img.onerror=()=>{img.onerror=null;img.src='/icon-192.png'}}$id('arabic-reciter')?.addEventListener('change',refreshPortrait);refreshPortrait();
async function resolvePlace(coords){const key=`place:${Number(coords.latitude).toFixed(3)}:${Number(coords.longitude).toFixed(3)}`,cached=localStorage.getItem(key),label=$id('location-label');if(cached){label.textContent=cached;return}try{const r=await fetch(`https://nominatim.openstreetmap.org/reverse?format=jsonv2&lat=${encodeURIComponent(coords.latitude)}&lon=${encodeURIComponent(coords.longitude)}&zoom=12&accept-language=tr`);if(!r.ok)throw Error();const j=await r.json(),a=j.address||{},district=a.town||a.district||a.suburb||a.county||a.city_district,city=a.city||a.province||a.state,text=[district,city].filter((x,i,arr)=>x&&arr.indexOf(x)===i).join(' / ')||'Bulunduğunuz konum';localStorage.setItem(key,text);label.textContent=text}catch(_){label.textContent='Bulunduğunuz konum'}}
const oldLoad=loadPrayerTimes;loadPrayerTimes=async function(coords){await oldLoad(coords);resolvePlace(coords)};if(appState.location)resolvePlace(appState.location);
function item(tag,cls,text){const el=document.createElement(tag);el.className=cls||'';if(text!=null)el.textContent=text;return el}
function duaCategory(x){if(x.kind==='Kur’an duası')return 'Kur’an’daki Dualar';if(x.kind==='Sünnette dua')return 'Peygamberimizin Duaları';return ['Günlük Hayat','Aile ve Huzur','Korunma','Şifa ve Afiyet','İman ve Maneviyat'][Math.abs((x.title||'').length)%5]}
let riyazV25=[];fetch('/riyazus.json?v=40').then(r=>r.ok?r.json():[]).then(x=>{riyazV25=x;if(guideKind==='hadis')renderGuideCategories()}).catch(()=>{});
function guideData(){return guideKind==='dua'?bigDuas:(riyazV25.length?riyazV25:window.bigHadiths||[])}function guideCategory(x){return guideKind==='dua'?duaCategory(x):(x.topic||x.category||'Genel')}
function renderGuideCategories(){const list=$id('dua-list');if(!list)return;if(guideKind==='esma')return window.renderDuasBaseV25?.();const data=guideData(),counts=new Map();data.forEach(x=>{const c=guideCategory(x);counts.set(c,(counts.get(c)||0)+1)});list.replaceChildren();const intro=item('div','category-intro');intro.innerHTML=`<span class="eyebrow">${guideKind==='dua'?'DUA KÜTÜPHANESİ':'HADİS KÜTÜPHANESİ'}</span><h2>Bir kategori seçin</h2><p>İçerikleri konuya göre daha düzenli inceleyebilirsiniz.</p>`;list.append(intro);const grid=item('div','category-grid');[['Tümü',data.length],...[...counts.entries()].sort((a,b)=>a[0].localeCompare(b[0],'tr'))].forEach(([name,count])=>{const b=item('button','category-tile');b.type='button';b.innerHTML=`<span>${name}</span><small>${count} içerik</small><b>›</b>`;b.onclick=()=>renderGuideResults(name==='Tümü'?'':name);grid.append(b)});list.append(grid)}
function renderGuideResults(category){const list=$id('dua-list'),data=guideData();list.replaceChildren();const top=item('div','guide-results-head'),back=item('button','category-back','‹ Kategoriler'),title=item('div','');title.innerHTML=`<span class="eyebrow">${category||'TÜMÜ'}</span><h2>${category||'Tüm içerikler'}</h2>`;back.onclick=renderGuideCategories;top.append(back,title);list.append(top);const search=item('label','library-search');search.innerHTML='⌕ <input placeholder="İçerik veya kaynak ara">';list.append(search);const cards=item('div','library-cards');list.append(cards);const paint=()=>{const term=normalize(search.querySelector('input').value);cards.replaceChildren();data.filter(x=>(!category||guideCategory(x)===category)&&(!term||normalize(`${x.title||''} ${x.text||''} ${x.source||''} ${x.narrator||''}`).includes(term))).forEach(x=>{const c=item('article',guideKind==='dua'?'dua-card':'dua-card hadith-card');if(guideKind==='dua'){let text=x.text;if(x.surah)text=state.corpus?.surahs[x.surah-1]?.ayahs[x.ayah-1]?.tr||x.title;c.append(item('span','dua-reference',`${guideCategory(x)} · ${x.source}`),item('h2','',x.title),item('p','dua-translation',text))}else c.append(item('span','dua-reference',`${guideCategory(x)} · ${x.source||''}`),item('p','hadith-text',x.text),item('p','hadith-narrator',x.narrator||''));cards.append(c)})};search.querySelector('input').oninput=paint;paint()}
const previousGuide=renderDuas;window.renderDuasBaseV25=previousGuide;renderDuas=function(){guideKind==='esma'?previousGuide():renderGuideCategories()};document.querySelectorAll('.content-choice').forEach(b=>b.addEventListener('click',()=>setTimeout(()=>{if(guideKind!=='esma')renderGuideCategories()},0)));
document.querySelectorAll('.back-button').forEach(b=>b.textContent='‹ Ana Menü');document.querySelector('.feature-card[data-page-target="duas"] strong')?.replaceChildren('Dua ve Hadisler');document.querySelector('.feature-card[data-page-target="duas"] small')?.replaceChildren('Dualar, hadisler ve Esmâü’l-Hüsnâ');
})();
